/**
 * Offline / PWA support: registers the service worker (`sw.js`, generated by cmd/build-web with a
 * content-hashed precache manifest), surfaces a non-blocking "Update available — reload" prompt
 * when a new deploy's worker is waiting, and requests persistent storage so the browser is less
 * likely to evict the ~9 MB offline cache (wasm engine + firmware image) between race days.
 *
 * Dev guard: on localhost / 127.0.0.1 the worker is never registered, and any previously
 * registered SlapRF worker + caches are removed, so on-the-fly rebuilt dist/app.js and wasm are
 * always fresh. (The un-built web/sw.js template is also inert by itself; see its header.)
 */

export interface StorageStatus {
  /** Whether the origin's storage is persistent (won't be evicted under storage pressure). */
  persisted: boolean;
  /** Bytes used by this origin, if the browser reports it. */
  usage?: number;
  /** Bytes available to this origin, if the browser reports it. */
  quota?: number;
}

export interface OfflineStatus {
  /** True when a service worker is registered and the app shell is available offline. */
  swEnabled: boolean;
  /** Why the service worker was not registered (dev host, unsupported, insecure context, error). */
  swDisabledReason?: string;
  storage?: StorageStatus;
}

const status: OfflineStatus = { swEnabled: false };
let storagePromise: Promise<StorageStatus> | null = null;

/** Current offline/PWA status snapshot (storage fields fill in once `getStorageStatus` resolves). */
export function getOfflineStatus(): OfflineStatus {
  return { ...status, storage: status.storage ? { ...status.storage } : undefined };
}

export function isDevHost(hostname: string = location.hostname): boolean {
  return (
    hostname === "localhost" ||
    hostname === "127.0.0.1" ||
    hostname === "[::1]" ||
    hostname === "::1" ||
    hostname.endsWith(".localhost")
  );
}

/**
 * Best-effort `navigator.storage.persist()` (called once) + `estimate()`. Never rejects.
 * Call again to refresh usage/quota; persist() is only requested the first time.
 */
export function getStorageStatus(): Promise<StorageStatus> {
  if (!storagePromise) {
    storagePromise = (async () => {
      let persisted = false;
      try {
        persisted = (await navigator.storage?.persisted?.()) ?? false;
        if (!persisted) persisted = (await navigator.storage?.persist?.()) ?? false;
      } catch {
        /* ignore: unsupported / denied */
      }
      return { persisted };
    })();
  }
  return storagePromise.then(async (base) => {
    const result: StorageStatus = { ...base };
    try {
      const est = await navigator.storage?.estimate?.();
      if (est) {
        result.usage = est.usage;
        result.quota = est.quota;
      }
    } catch {
      /* ignore */
    }
    status.storage = result;
    return result;
  });
}

function showUpdatePrompt(worker: ServiceWorker): void {
  if (document.getElementById("slaprf-update-toast")) return;
  const toast = document.createElement("div");
  toast.id = "slaprf-update-toast";
  toast.className = "update-toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");
  toast.innerHTML = `
    <span class="update-toast-text">Update available</span>
    <button type="button" class="btn btn-primary btn-sm" data-action="reload">Reload</button>
    <button type="button" class="btn btn-ghost btn-sm" data-action="dismiss" aria-label="Dismiss">Later</button>
  `;
  toast.querySelector<HTMLButtonElement>('[data-action="reload"]')?.addEventListener("click", (ev) => {
    const btn = ev.currentTarget as HTMLButtonElement;
    btn.disabled = true;
    btn.textContent = "Updating…";
    reloadOnControllerChange = true;
    worker.postMessage({ type: "SKIP_WAITING" });
    // Fallback in case controllerchange never fires (e.g. worker already redundant).
    window.setTimeout(() => window.location.reload(), 4000);
  });
  toast.querySelector<HTMLButtonElement>('[data-action="dismiss"]')?.addEventListener("click", () => toast.remove());
  document.body.appendChild(toast);
}

let reloadOnControllerChange = false;

function watchForUpdates(reg: ServiceWorkerRegistration): void {
  const offerIfWaiting = () => {
    // Only prompt when an older worker controls this page; the very first install needs no reload.
    if (reg.waiting && navigator.serviceWorker.controller) showUpdatePrompt(reg.waiting);
  };
  offerIfWaiting();
  reg.addEventListener("updatefound", () => {
    const installing = reg.installing;
    if (!installing) return;
    installing.addEventListener("statechange", () => {
      if (installing.state === "installed") offerIfWaiting();
    });
  });
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (!reloadOnControllerChange) return;
    reloadOnControllerChange = false;
    window.location.reload();
  });
  // Long sessions at the field: check for a new deploy hourly and when the tab regains focus.
  const check = () => {
    if (navigator.onLine) reg.update().catch(() => undefined);
  };
  window.setInterval(check, 60 * 60 * 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") check();
  });
}

async function cleanupDevWorkers(): Promise<void> {
  try {
    const regs = await navigator.serviceWorker.getRegistrations();
    await Promise.all(regs.map((r) => r.unregister()));
    if ("caches" in window) {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith("slaprf-precache-")).map((n) => caches.delete(n)));
    }
  } catch {
    /* ignore */
  }
}

/**
 * Call once from the app entry. Never throws and never blocks boot.
 */
export function installOffline(): void {
  void getStorageStatus().then((s) => {
    console.info(
      `[offline] storage persisted=${s.persisted}` +
        (s.usage !== undefined && s.quota !== undefined
          ? ` usage=${(s.usage / 1048576).toFixed(1)}MB quota=${(s.quota / 1048576).toFixed(0)}MB`
          : ""),
    );
  });

  if (!("serviceWorker" in navigator)) {
    status.swDisabledReason = "unsupported";
    return;
  }
  if (isDevHost()) {
    status.swDisabledReason = "dev-host";
    void cleanupDevWorkers();
    return;
  }
  if (!window.isSecureContext) {
    status.swDisabledReason = "insecure-context";
    return;
  }

  const register = () => {
    // Absolute: the site is served from the domain root (slaprf.app), and a relative URL would
    // resolve against nested path deep links (e.g. /a/b → /a/sw.js).
    navigator.serviceWorker
      .register("/sw.js", { scope: "/" })
      .then((reg) => {
        status.swEnabled = true;
        watchForUpdates(reg);
      })
      .catch((err) => {
        status.swDisabledReason = `error: ${err instanceof Error ? err.message : String(err)}`;
        console.warn("[offline] service worker registration failed:", err);
      });
  };
  // Register after load so precaching (~12 MB) doesn't compete with the first paint.
  if (document.readyState === "complete") register();
  else window.addEventListener("load", register, { once: true });
}
